"""Export the design artifacts to plain-text files for the C++ pipeline.
model.txt      -> server home (weights, per-unit Chebyshev coefs/domains; NO secrets)
client_meta.txt-> client home (standardized feature bounds for the airtight box check,
                  logit threshold; NO weights - trust-model-safe)"""
import json, sys
import numpy as np, pandas as pd

REPO = sys.argv[1] if len(sys.argv) > 1 else "."
ART = f"{REPO}/model/surrogate"; APP = f"{REPO}/data/inputs"
import os; os.makedirs(APP, exist_ok=True)
S = json.load(open(f"{ART}/mlp_surrogate.json"))
F, H = len(S["feature_cols"]), S["hidden"]
mu, sd = np.array(S["mu"]), np.array(S["sd"])

with open(f"{APP}/model.txt", "w") as f:
    f.write(f"{F} {H} {S['cheb_degree']}\n")
    for row in S["W1"]: f.write(" ".join(f"{v:.17g}" for v in row) + "\n")
    f.write(" ".join(f"{v:.17g}" for v in S["b1"]) + "\n")
    f.write(" ".join(f"{v:.17g}" for v in S["W2"]) + "\n")
    f.write(f"{S['b2']:.17g}\n")
    for k in range(H):
        f.write(f"{S['dom_lo'][k]:.17g} {S['dom_hi'][k]:.17g}\n")
        # OpenFHE EvalChebyshevSeries uses the classical convention
        # c0/2 + sum c_k T_k; numpy's Chebyshev uses plain c0 + sum c_k T_k.
        # Double c0 so the encrypted circuit matches the twin.
        cs = list(S["cheb_coefs"][k]); cs[0] *= 2.0
        f.write(" ".join(f"{c:.17g}" for c in cs) + "\n")

box = pd.read_csv(f"{ART}/feature_bounds.csv")
zlo = (box["min"].to_numpy() - mu) / sd
zhi = (box["max"].to_numpy() - mu) / sd
with open(f"{APP}/client_meta.txt", "w") as f:
    f.write(f"{F}\n")
    f.write(" ".join(f"{v:.17g}" for v in zlo) + "\n")
    f.write(" ".join(f"{v:.17g}" for v in zhi) + "\n")
    f.write(f"{S['threshold_logit']:.17g}\n")
print("wrote", APP + "/model.txt", "and client_meta.txt")
